using UnityEngine;
using NWH.VehiclePhysics2;
using LWS.TruckTaxi;
namespace LWS.TruckSports {
 // Optional full-tractor adapter for Taxi-based sports. NWH remains the only
 // powertrain/wheel authority; the older event-wheel path stays unchanged.
 [DefaultExecutionOrder(-80)]public sealed class SportsNwhTractorMotor:MonoBehaviour {
  public VehicleController vehicle;public TruckTaxiVehicleHandlingOverride handling;public SportsSettings settings;
  public bool forceSpatialAudio;public float gripScale=1;float[] originalLongitudinal,originalLateral;
  public bool Grounded{get{if(vehicle==null||wheels==null)return false;foreach(var wheel in wheels)if(wheel!=null&&wheel.enabled&&wheel.IsGrounded)return true;return false;}}
  SportsEventTruck owner;NWH.WheelController3D.WheelController[] wheels;Rigidbody[] secondary;Vector3[] localPositions;Quaternion[] localRotations;bool enabledForPlay;AudioSource[] vendorAudio;bool audioLocal;int audioRetries;float nextAudioRefresh;
  void Awake(){owner=GetComponent<SportsEventTruck>();Cache();}void Cache(){if(secondary==null){var all=GetComponentsInChildren<Rigidbody>(true);var list=new System.Collections.Generic.List<Rigidbody>();foreach(var body in all)if(body.gameObject!=gameObject)list.Add(body);secondary=list.ToArray();localPositions=new Vector3[secondary.Length];localRotations=new Quaternion[secondary.Length];for(int i=0;i<secondary.Length;i++){localPositions[i]=transform.InverseTransformPoint(secondary[i].position);localRotations[i]=Quaternion.Inverse(transform.rotation)*secondary[i].rotation;}}
   if(wheels==null){wheels=GetComponentsInChildren<NWH.WheelController3D.WheelController>(true);originalLongitudinal=new float[wheels.Length];originalLateral=new float[wheels.Length];for(int i=0;i<wheels.Length;i++){originalLongitudinal[i]=wheels[i].LongitudinalFrictionGrip;originalLateral[i]=wheels[i].LateralFrictionGrip;}}}
  public void ResetAttachedBodies(){Cache();for(int i=0;i<secondary.Length;i++){var body=secondary[i];if(body==null)continue;if(!body.isKinematic)body.linearVelocity=body.angularVelocity=Vector3.zero;body.position=transform.TransformPoint(localPositions[i]);body.rotation=transform.rotation*localRotations[i];body.WakeUp();}}
  public void AddAssemblyVelocity(Vector3 velocity){Cache();var root=GetComponent<Rigidbody>();if(!root.isKinematic){root.linearVelocity+=velocity;root.WakeUp();}foreach(var body in secondary)if(body!=null&&!body.isKinematic){body.linearVelocity+=velocity;body.WakeUp();}}
  public void Configure(){Cache();ConfigureAudio();vehicle.input.autoSetInput=false;vehicle.powertrain.transmission.transmissionType=NWH.VehiclePhysics2.Powertrain.TransmissionComponent.TransmissionShiftType.Automatic;vehicle.powertrain.transmission.automaticTransmissionDNRShiftType=NWH.VehiclePhysics2.Powertrain.TransmissionComponent.AutomaticTransmissionDNRShiftType.Auto;vehicle.powertrain.engine.autoStartOnThrottle=true;if(handling!=null&&!handling.Applied)handling.Initialize(vehicle);}
  void ConfigureAudio(){if(vehicle==null||owner==null||owner.session==null)return;audioLocal=!forceSpatialAudio&&owner.session.setup.players[owner.slot].source!=LWS.TruckBowling.BowlingSource.AI;vehicle.soundManager.spatialBlend=audioLocal?0:1;vendorAudio=null;audioRetries=0;nextAudioRefresh=0;}
  void LateUpdate(){if(enabledForPlay&&vehicle!=null&&Time.unscaledTime>=nextAudioRefresh&&audioRetries<4){nextAudioRefresh=Time.unscaledTime+.5f;audioRetries++;vendorAudio=vehicle.GetComponentsInChildren<AudioSource>(true);foreach(var source in vendorAudio)source.spatialBlend=audioLocal?0:1;if(vehicle.soundManager.engineRunningComponent.source!=null)audioRetries=4;}if(vehicle!=null&&settings!=null){vehicle.soundManager.masterVolume=enabledForPlay&&owner!=null&&owner.session!=null&&owner.session.Live&&Application.isFocused?settings.sfx*.6f/Mathf.Sqrt(HumanMixCount()):0;}}
  int HumanMixCount(){if(!audioLocal||owner?.session==null)return 1;int humans=0;for(int i=0;i<owner.session.setup.count;i++)if(owner.session.setup.players[i].source!=LWS.TruckBowling.BowlingSource.AI)humans++;return Mathf.Max(1,humans);}
  public void Power(bool enabled){Cache();enabledForPlay=enabled;if(vehicle==null)return;vehicle.input.autoSetInput=false;vehicle.input.states=default;vehicle.enabled=enabled;foreach(var wheel in wheels)if(wheel!=null)wheel.enabled=enabled;}
  public void Drive(Vector2 drive){if(!enabledForPlay||vehicle==null)return;vehicle.input.autoSetInput=false;vehicle.input.states.steering=vehicle.input.states.steeringRaw=Mathf.Clamp(drive.x,-1,1);vehicle.input.states.throttle=vehicle.input.states.throttleRaw=Mathf.Clamp01(drive.y);vehicle.input.states.brakes=vehicle.input.states.brakesRaw=Mathf.Clamp01(-drive.y);vehicle.input.states.handbrake=vehicle.input.states.handbrakeRaw=0;for(int i=0;i<wheels.Length;i++){wheels[i].LongitudinalFrictionGrip=originalLongitudinal[i]*gripScale;wheels[i].LateralFrictionGrip=originalLateral[i]*gripScale;}}
 }
}
